test('global value maximization over attractive conflict',()=>{const a={...base,meetings:[m('a','09:00',60,8,[],['A']),m('b','09:00',60,7,[],['A']),m('c','10:00',60,7,[],['A'])]};assert.equal(book(a).value,15);assert.deepEqual(book(a).bookings.map(x=>x.meeting_id),['a','c']);});
test('directed consecutive setup uses immediate predecessor',()=>{const a={...base,meetings:[m('a','09:00',30,5,['p']),m('b','09:40',20,5,['p']),m('c','10:00',20,20,['p'])]};const r=book(a);assert.equal(r.value,30);assert.deepEqual(r.bookings.map(x=>x.meeting_id),['a','b','c']);});
test('DST fold alternatives and nonexistent local start',()=>{const a={...base,range_start:'2025-11-02T00:00:00Z',range_end:'2025-11-03T00:00:00Z',meetings:[{...m('fold','01:30',30,4,[],['A']),zone:'America/New_York',local_start:'2025-11-02T01:30',fold:'either'},{...m('gap','02:30',30,99,[],['B']),zone:'America/New_York',local_start:'2025-03-09T02:30'}]};const r=book(a);assert.equal(r.value,4);assert.equal(r.bookings[0].start,'2025-11-02T05:30:00.000Z');});
test('room blocks and lexicographic tie order',()=>{const a={...base,blocks:[{room_id:'A',start:'2025-01-01T09:00:00Z',end:'2025-01-01T10:00:00Z'}],meetings:[m('z','09:00',30,3,[],['A','B']),m('a','09:00',30,3,[],['B','A'])]};assert.equal(book(a).bookings[0].meeting_id,'a');});

